        private static bool IsUtilityFacilityPrefab(EntityManager em,Entity e)=>em.Exists(e)&&(em.HasComponent<PowerPlantData>(e)||em.HasComponent<Game.Prefabs.TransformerData>(e)||em.HasComponent<BatteryData>(e)||em.HasComponent<WaterPumpingStationData>(e)||em.HasComponent<SewageOutletData>(e)||em.HasComponent<WaterTowerData>(e)||em.HasComponent<TelecomFacilityData>(e));
        private static bool IsPlaceableUtilityFacilityPrefab(EntityManager em,Entity e)=>IsUtilityFacilityPrefab(em,e)&&em.HasComponent<BuildingData>(e)&&em.HasComponent<PlaceableObjectData>(e)&&!em.HasComponent<ServiceUpgradeData>(e);
        private static string UtilityFacilityKind(EntityManager em,Entity e,string prefabName=null){if(!string.IsNullOrEmpty(prefabName)){if(prefabName.StartsWith("WaterTower",StringComparison.OrdinalIgnoreCase))return "water_tower";if(prefabName.IndexOf("Sewage",StringComparison.OrdinalIgnoreCase)>=0||prefabName.IndexOf("Wastewater",StringComparison.OrdinalIgnoreCase)>=0)return "sewage";}return em.HasComponent<PowerPlantData>(e)?"power_plant":em.HasComponent<Game.Prefabs.TransformerData>(e)?"transformer":em.HasComponent<BatteryData>(e)?"battery":em.HasComponent<WaterTowerData>(e)?"water_tower":em.HasComponent<SewageOutletData>(e)?"sewage":em.HasComponent<WaterPumpingStationData>(e)?"water_pump":"telecom";}
        private Entity ResolveUtilityFacilityPrefab(string wanted,World world){var em=world.EntityManager;var ps=world.GetExistingSystemManaged<PrefabSystem>();using(var q=em.CreateEntityQuery(ComponentType.ReadOnly<PrefabData>()))using(var es=q.ToEntityArray(Allocator.Temp))foreach(var e in es)if(IsPlaceableUtilityFacilityPrefab(em,e)&&ps.TryGetPrefab<PrefabBase>(e,out var p)&&string.Equals(p.name,wanted,StringComparison.OrdinalIgnoreCase))return e;throw new QueryException("UTILITY_FACILITY_PREFAB_NOT_FOUND","Use an exact name from list_utility_facility_prefabs.");}
        private JObject UtilityFacilityPrefabRow(World world,Entity e){var em=world.EntityManager;var ps=world.GetExistingSystemManaged<PrefabSystem>();ps.TryGetPrefab<PrefabBase>(e,out var p);var row=new JObject{{"name",p?.name},{"kind",UtilityFacilityKind(em,e,p?.name)},{"locked",RoadOperation.IsLocked(em,e)}};if(em.HasComponent<PlaceableObjectData>(e)){var d=em.GetComponentData<PlaceableObjectData>(e);row["construction_cost"]=d.m_ConstructionCost;row["placement_flags"]=d.m_Flags.ToString();}if(em.HasComponent<BuildingData>(e)){var d=em.GetComponentData<BuildingData>(e);row["lot_cells"]=new JObject{{"width",d.m_LotSize.x},{"depth",d.m_LotSize.y}};row["requires_road"]=(d.m_Flags&Game.Prefabs.BuildingFlags.RequireRoad)!=0;}if(em.HasComponent<ObjectGeometryData>(e)){var d=em.GetComponentData<ObjectGeometryData>(e);row["size_m"]=new JObject{{"x",d.m_Size.x},{"y",d.m_Size.y},{"z",d.m_Size.z}};}return row;}
        private JObject ListUtilityFacilityPrefabs(JObject args,World world){string search=((string)args["search"]??"").Trim(),kind=((string)args["kind"]??"all").ToLowerInvariant();var allowed=new[]{"all","power_plant","transformer","battery","water_pump","sewage","water_tower","telecom"};if(!allowed.Contains(kind))throw new QueryException("INVALID_ARGUMENT","Unsupported utility facility kind.");bool unlocked=(bool?)args["unlocked_only"]??true;int offset=ComponentInspector.Int(args,"offset",0,0,10000),limit=ComponentInspector.Int(args,"limit",50,1,100);var rows=new List<JObject>();var em=world.EntityManager;using(var q=em.CreateEntityQuery(ComponentType.ReadOnly<PrefabData>()))using(var es=q.ToEntityArray(Allocator.Temp))foreach(var e in es){if(!IsPlaceableUtilityFacilityPrefab(em,e))continue;var r=UtilityFacilityPrefabRow(world,e);if(unlocked&&(bool)r["locked"]||kind!="all"&&(string)r["kind"]!=kind||search.Length>0&&((string)r["name"]??"").IndexOf(search,StringComparison.OrdinalIgnoreCase)<0)continue;rows.Add(r);}rows=rows.OrderBy(x=>(string)x["name"]).ToList();return new JObject{{"total",rows.Count},{"offset",offset},{"next_offset",offset+limit<rows.Count?new JValue(offset+limit):null},{"items",new JArray(rows.Skip(offset).Take(limit))}};}
        private Entity ResolveUtilityFacility(JObject args,World world){var e=ParseEntity((string)args["facility_id"],world.EntityManager);var em=world.EntityManager;if(!em.Exists(e)||!em.HasComponent<Building>(e)||!em.HasComponent<PrefabRef>(e)||em.HasComponent<Deleted>(e)||em.HasComponent<Temp>(e)||!IsUtilityFacilityPrefab(em,em.GetComponentData<PrefabRef>(e).m_Prefab))throw new QueryException("UTILITY_FACILITY_NOT_FOUND","facility_id must identify a permanent utility facility.");return e;}
        private JObject UtilityFacilityRow(World world,Entity e){var em=world.EntityManager;var ps=world.GetExistingSystemManaged<PrefabSystem>();var prefab=em.GetComponentData<PrefabRef>(e).m_Prefab;ps.TryGetPrefab<PrefabBase>(prefab,out var p);var t=em.GetComponentData<Game.Objects.Transform>(e);var building=em.GetComponentData<Building>(e);var row=new JObject{{"facility_id",m_Session+":"+e.Index+":"+e.Version},{"name",Name(world,e)},{"prefab",p?.name},{"kind",UtilityFacilityKind(em,prefab,p?.name)},{"position",PointJson(t.m_Position)},{"road_edge_id",OptionalEntity(m_Session,building.m_RoadEdge)}};if(em.HasComponent<ElectricityProducer>(e)){var d=em.GetComponentData<ElectricityProducer>(e);row["electricity_capacity"]=d.m_Capacity;row["last_electricity_production"]=d.m_LastProduction;}if(em.HasComponent<Game.Buildings.Battery>(e)){var d=em.GetComponentData<Game.Buildings.Battery>(e);row["stored_energy"]=d.m_StoredEnergy;row["battery_capacity"]=d.m_Capacity;row["last_energy_flow"]=d.m_LastFlow;}if(em.HasComponent<Game.Buildings.WaterPumpingStation>(e)){var d=em.GetComponentData<Game.Buildings.WaterPumpingStation>(e);row["water_capacity"]=d.m_Capacity;row["last_water_production"]=d.m_LastProduction;row["water_pollution"]=d.m_Pollution;}if(em.HasComponent<Game.Buildings.SewageOutlet>(e)){var d=em.GetComponentData<Game.Buildings.SewageOutlet>(e);row["sewage_capacity"]=d.m_Capacity;row["last_sewage_processed"]=d.m_LastProcessed;row["last_sewage_purified"]=d.m_LastPurified;}if(em.HasComponent<Game.Buildings.WaterTower>(e)){var d=em.GetComponentData<Game.Buildings.WaterTower>(e);row["stored_water"]=d.m_StoredWater;row["polluted_water"]=d.m_Polluted;}if(em.HasComponent<Game.Buildings.TelecomFacility>(e))row["telecom_flags"]=em.GetComponentData<Game.Buildings.TelecomFacility>(e).m_Flags.ToString();if(em.HasBuffer<Efficiency>(e)){var b=em.GetBuffer<Efficiency>(e,true);row["efficiency_factors"]=new JArray(Enumerable.Range(0,b.Length).Select(i=>(object)b[i].m_Efficiency));}return row;}
        private JObject ListUtilityFacilities(JObject args,World world){string kind=((string)args["kind"]??"all").ToLowerInvariant();var allowed=new[]{"all","power_plant","transformer","battery","water_pump","sewage","water_tower","telecom"};if(!allowed.Contains(kind))throw new QueryException("INVALID_ARGUMENT","Unsupported utility facility kind.");var rows=new List<JObject>();var em=world.EntityManager;using(var q=em.CreateEntityQuery(ComponentType.ReadOnly<Building>(),ComponentType.ReadOnly<PrefabRef>(),ComponentType.ReadOnly<Game.Objects.Transform>(),ComponentType.Exclude<Deleted>(),ComponentType.Exclude<Temp>()))using(var es=q.ToEntityArray(Allocator.Temp))foreach(var e in es){var p=em.GetComponentData<PrefabRef>(e).m_Prefab;if(!IsUtilityFacilityPrefab(em,p))continue;var row=UtilityFacilityRow(world,e);if(kind=="all"||(string)row["kind"]==kind)rows.Add(row);}return new JObject{{"total",rows.Count},{"items",new JArray(rows)}};}
        private JObject GetUtilityFacility(JObject args,World world)=>UtilityFacilityRow(world,ResolveUtilityFacility(args,world));
        private static Game.Net.Layer UtilityConnectionLayer(string connection)
        {
            switch ((connection ?? "auto").Trim().ToLowerInvariant())
            {
                case "high_voltage": return Game.Net.Layer.PowerlineHigh;
                case "low_voltage": return Game.Net.Layer.PowerlineLow;
                case "fresh_water": return Game.Net.Layer.WaterPipe;
                case "sewage": return Game.Net.Layer.SewagePipe;
                case "stormwater": return Game.Net.Layer.StormwaterPipe;
                default: return Game.Net.Layer.All;
            }
        }
        private static Game.Net.Layer UtilityLayers(EntityManager em, Entity prefab)
        {
            if (!em.Exists(prefab) || !em.HasComponent<LocalConnectData>(prefab)) return Game.Net.Layer.None;
            return em.GetComponentData<LocalConnectData>(prefab).m_Layers;
        }
        private static string UtilityConnectionName(EntityManager em, Entity node, Entity prefab)
        {
            if (em.HasComponent<ElectricityConnectionData>(prefab))
            {
                var voltage = em.GetComponentData<ElectricityConnectionData>(prefab).m_Voltage.ToString();
                return voltage.IndexOf("High", StringComparison.OrdinalIgnoreCase) >= 0 ? "high_voltage" : "low_voltage";
            }
            if (em.HasComponent<WaterPipeConnectionData>(prefab))
            {
                var data = em.GetComponentData<WaterPipeConnectionData>(prefab);
                if (data.m_SewageCapacity > 0) return "sewage";
                if (data.m_StormCapacity > 0) return "stormwater";
                if (data.m_FreshCapacity > 0) return "fresh_water";
            }
            return null;
        }
        private static bool UtilityNodeSupports(EntityManager em, Entity node, Game.Net.Layer requested)
        {
            if (!em.Exists(node) || !em.HasComponent<Node>(node) || !em.HasComponent<PrefabRef>(node)) return false;
            var prefab = em.GetComponentData<PrefabRef>(node).m_Prefab;
            var connection = UtilityConnectionName(em, node, prefab);
            if (connection == null) return false;
            if (requested == Game.Net.Layer.All) return true;
            return (UtilityConnectionLayer(connection) & requested) != 0;
        }
        private string UtilityEntityId(Entity e) => e == Entity.Null ? null : m_Session + ":" + e.Index + ":" + e.Version;
        private IEnumerable<Entity> UtilityFacilityPortNodes(World world, Entity facility)
        {
            var em = world.EntityManager; var seen = new HashSet<Entity>(); var roots = new List<Entity> { facility };
            if (em.HasBuffer<InstalledUpgrade>(facility))
            {
                var upgrades = em.GetBuffer<InstalledUpgrade>(facility, true);
                for (int i = 0; i < upgrades.Length; i++) if (upgrades[i].m_Upgrade != Entity.Null && em.Exists(upgrades[i].m_Upgrade) && !em.HasComponent<Deleted>(upgrades[i].m_Upgrade)) roots.Add(upgrades[i].m_Upgrade);
            }
            foreach (var root in roots) if (em.HasBuffer<Game.Net.SubNet>(root))
            {
                var subnets = em.GetBuffer<Game.Net.SubNet>(root, true);
                for (int i = 0; i < subnets.Length; i++)
                {
                    var node = subnets[i].m_SubNet;
                    if (!seen.Add(node) || !em.Exists(node) || em.HasComponent<Deleted>(node) || em.HasComponent<Temp>(node) || !em.HasComponent<Node>(node) || !em.HasComponent<PrefabRef>(node)) continue;
                    var prefab = em.GetComponentData<PrefabRef>(node).m_Prefab;
                    if (UtilityConnectionName(em, node, prefab) != null) yield return node;
                }
            }
        }
        private JObject UtilityConnectionPointRow(World world, Entity facility, Entity node)
        {
            var em = world.EntityManager; var prefab = em.GetComponentData<PrefabRef>(node).m_Prefab; var ps = world.GetExistingSystemManaged<PrefabSystem>(); ps.TryGetPrefab<PrefabBase>(prefab, out var pf);
            var data = new JObject { ["node_id"] = UtilityEntityId(node), ["facility_id"] = UtilityEntityId(facility), ["position"] = PointJson(em.GetComponentData<Node>(node).m_Position), ["connection"] = UtilityConnectionName(em, node, prefab), ["prefab"] = pf?.name, ["layers"] = UtilityLayers(em, prefab).ToString(), ["connected_edge_count"] = 0, ["connected_edge_ids"] = new JArray() };
            if (em.HasComponent<ElectricityConnectionData>(prefab)) { var x = em.GetComponentData<ElectricityConnectionData>(prefab); data["capacity"] = x.m_Capacity; data["direction"] = x.m_Direction.ToString(); data["voltage"] = x.m_Voltage.ToString(); }
            if (em.HasComponent<WaterPipeConnectionData>(prefab)) { var x = em.GetComponentData<WaterPipeConnectionData>(prefab); data["fresh_capacity"] = x.m_FreshCapacity; data["sewage_capacity"] = x.m_SewageCapacity; data["storm_capacity"] = x.m_StormCapacity; }
            if (em.HasBuffer<ConnectedEdge>(node)) { var edges = em.GetBuffer<ConnectedEdge>(node, true); var ids = (JArray)data["connected_edge_ids"]; for (int i = 0; i < edges.Length; i++) if (IsPermanentUtility(em, edges[i].m_Edge)) ids.Add(UtilityEntityId(edges[i].m_Edge)); data["connected_edge_count"] = ids.Count; }
            data["externally_connected"] = (int)data["connected_edge_count"] > 0;
            return data;
        }
        private JObject ListUtilityConnectionPoints(JObject args, World world)
        {
            var facility = ResolveUtilityFacility(args, world); var requested = ((string)args["connection"] ?? "auto").Trim().ToLowerInvariant();
            var rows = UtilityFacilityPortNodes(world, facility).Select(node => UtilityConnectionPointRow(world, facility, node)).Where(row => requested == "auto" || string.Equals((string)row["connection"], requested, StringComparison.OrdinalIgnoreCase)).ToList();
            return new JObject { ["facility_id"] = UtilityEntityId(facility), ["connection"] = requested, ["total"] = rows.Count, ["items"] = new JArray(rows) };
        }
        private JObject FindCompatibleUtilityTargets(JObject args, World world)
        {
            var facility = ResolveUtilityFacility(args, world); var requested = ((string)args["connection"] ?? "auto").Trim().ToLowerInvariant(); var mask = UtilityConnectionLayer(requested); var radius = BuildingNumber(args, "search_radius_m", 500, 16, 5000); var limit = ComponentInspector.Int(args, "limit", 32, 1, 256); Entity requestedPrefab = Entity.Null; if (args["utility_prefab"] != null) requestedPrefab = ResolveUtilityPrefab((string)args["utility_prefab"], world);
            var ports = UtilityFacilityPortNodes(world, facility).Select(node => UtilityConnectionPointRow(world, facility, node)).Where(row => requested == "auto" || string.Equals((string)row["connection"], requested, StringComparison.OrdinalIgnoreCase)).ToList();
            if (ports.Count == 0) throw new QueryException("UTILITY_CONNECTION_POINT_NOT_FOUND", "The facility has no matching native connection port; check installed upgrades and connection kind.");
            if (requestedPrefab != Entity.Null) mask = UtilityLayers(world.EntityManager, requestedPrefab);
            else if (requested == "auto") mask = ports.Select(row => UtilityConnectionLayer((string)row["connection"])).Aggregate(Game.Net.Layer.None, (current, value) => current | value);
            ports = ports.Where(port => (UtilityConnectionLayer((string)port["connection"]) & mask) != 0).ToList();
            if (ports.Count == 0) throw new QueryException("INCOMPATIBLE_UTILITY_PREFAB", "The selected utility prefab does not match any facility connection port.");
            var em = world.EntityManager; var candidates = new List<JObject>(); using (var q = em.CreateEntityQuery(ComponentType.ReadOnly<Edge>(), ComponentType.ReadOnly<Curve>(), ComponentType.ReadOnly<PrefabRef>(), ComponentType.Exclude<Deleted>(), ComponentType.Exclude<Temp>())) using (var edges = q.ToEntityArray(Allocator.Temp)) foreach (var edge in edges)
            {
                if (!IsPermanentUtility(em, edge)) continue; var prefab = em.GetComponentData<PrefabRef>(edge).m_Prefab; var edgeLayers = UtilityLayers(em, prefab); if ((edgeLayers & mask) == 0) continue; var e = em.GetComponentData<Edge>(edge); var endpoints = new[] { e.m_Start, e.m_End }; foreach (var node in endpoints) if (em.HasComponent<Node>(node)) foreach (var port in ports) { if ((edgeLayers & UtilityConnectionLayer((string)port["connection"])) == 0) continue; var pp = (JObject)port["position"]; var dx = (float)pp["x"] - em.GetComponentData<Node>(node).m_Position.x; var dz = (float)pp["z"] - em.GetComponentData<Node>(node).m_Position.z; var distance = math.sqrt(dx * dx + dz * dz); if (distance <= radius) candidates.Add(new JObject { ["facility_port"] = port.DeepClone(), ["target_node_id"] = UtilityEntityId(node), ["target_edge_id"] = UtilityEntityId(edge), ["target_position"] = PointJson(em.GetComponentData<Node>(node).m_Position), ["utility_prefab"] = world.GetExistingSystemManaged<PrefabSystem>().GetPrefab<PrefabBase>(prefab).name, ["layers"] = edgeLayers.ToString(), ["distance_m"] = distance }); }
            }
            var unique = candidates.GroupBy(x => (string)x["facility_port"]["node_id"] + "|" + (string)x["target_node_id"] + "|" + (string)x["utility_prefab"]).Select(g => g.OrderBy(x => (float)x["distance_m"]).First()).OrderBy(x => (float)x["distance_m"]).Take(limit).ToList(); return new JObject { ["facility_id"] = UtilityEntityId(facility), ["connection"] = requested, ["total"] = unique.Count, ["items"] = new JArray(unique) };
        }
        private JObject PlanUtilityFacilitySite(JObject args,World world){var p=ResolveUtilityFacilityPrefab((string)args["building_prefab"],world);var f=world.EntityManager.GetComponentData<PlaceableObjectData>(p).m_Flags;return (f&(Game.Objects.PlacementFlags.Shoreline|Game.Objects.PlacementFlags.Floating|Game.Objects.PlacementFlags.RoadEdge|Game.Objects.PlacementFlags.RoadNode))!=0?PlanSpecialBuildingSite(args,world):PlanBuildingSite(args,world);}
        private void ValidateUtilityFacilityOperation(BuildingOperation op,World world){var p=op.Prefab!=Entity.Null?op.Prefab:op.OriginalPrefab;if(!IsUtilityFacilityPrefab(world.EntityManager,p))throw new QueryException("NOT_A_UTILITY_FACILITY_OPERATION","The operation does not target a utility facility.");}
        private JObject PreviewUtilityFacility(JObject args,World world,string type){if(type=="place")ResolveUtilityFacilityPrefab((string)args["building_prefab"],world);else ResolveUtilityFacility(new JObject{{"facility_id",args["facility_id"]}},world);var copy=(JObject)args.DeepClone();if(copy["facility_id"]!=null){copy["building_id"]=copy["facility_id"];copy.Remove("facility_id");}var op=PreviewBuildingOperation(copy,world,type);ValidateUtilityFacilityOperation(op,world);return op.Json();}
        private JObject GetUtilityFacilityOperation(JObject args,World world){var op=BuildingOperationById(args);ValidateUtilityFacilityOperation(op,world);return op.Json();}
        private JObject ApplyUtilityFacilityOperation(JObject args,World world){var op=BuildingOperationById(args);ValidateUtilityFacilityOperation(op,world);return ApplyBuildingOperation(args,world);}
        private JObject CancelUtilityFacilityOperation(JObject args,World world){var op=BuildingOperationById(args);ValidateUtilityFacilityOperation(op,world);return CancelBuildingOperation(args);}

        private static bool IsUtilityPrefab(EntityManager em,Entity p)=>em.Exists(p)&&(em.HasComponent<PowerLineData>(p)||em.HasComponent<PipelineData>(p));
        private static Game.Net.Layer UtilityNetworkMask(EntityManager em,Entity p)=>em.HasComponent<LocalConnectData>(p)?em.GetComponentData<LocalConnectData>(p).m_Layers:em.HasComponent<PowerLineData>(p)?(Game.Net.Layer.PowerlineLow|Game.Net.Layer.PowerlineHigh):Game.Net.Layer.None;
        private static string UtilityNetworkKind(EntityManager em,Entity p){var layers=UtilityNetworkMask(em,p);bool power=(layers&(Game.Net.Layer.PowerlineLow|Game.Net.Layer.PowerlineHigh))!=0,water=(layers&Game.Net.Layer.WaterPipe)!=0,sewage=(layers&Game.Net.Layer.SewagePipe)!=0,storm=(layers&Game.Net.Layer.StormwaterPipe)!=0;if(power)return "electricity";if(water&&sewage)return "water_sewage";if(water)return "water";if(sewage)return "sewage";if(storm)return "stormwater";return "resource";}
        private static bool IsMarkerUtilityPrefab(EntityManager em,Entity p)=>em.HasComponent<NetGeometryData>(p)&&em.GetComponentData<NetGeometryData>(p).m_Flags.ToString().IndexOf("Marker",StringComparison.OrdinalIgnoreCase)>=0;
        private Entity[] UtilityPrefabs(EntityManager em){using(var q=em.CreateEntityQuery(ComponentType.ReadOnly<NetData>(),ComponentType.ReadOnly<NetGeometryData>(),ComponentType.ReadOnly<PlaceableNetData>(),ComponentType.ReadOnly<PrefabData>()))using(var es=q.ToEntityArray(Allocator.Temp))return es.Where(e=>IsUtilityPrefab(em,e)).ToArray();}
        private Entity ResolveUtilityPrefab(string wanted,World world){var em=world.EntityManager;var ps=world.GetExistingSystemManaged<PrefabSystem>();foreach(var e in UtilityPrefabs(em))if(!IsMarkerUtilityPrefab(em,e)&&ps.TryGetPrefab<PrefabBase>(e,out var p)&&(p is PowerLinePrefab||p is PipelinePrefab)&&string.Equals(p.name,wanted,StringComparison.OrdinalIgnoreCase))return e;throw new QueryException("UTILITY_PREFAB_NOT_FOUND","Use an exact non-marker name from list_utility_network_prefabs.");}
        private JObject UtilityPrefabRow(World world,Entity e){var em=world.EntityManager;var ps=world.GetExistingSystemManaged<PrefabSystem>();ps.TryGetPrefab<PrefabBase>(e,out var p);var g=em.GetComponentData<NetGeometryData>(e);var d=em.GetComponentData<PlaceableNetData>(e);var row=new JObject{{"name",p?.name},{"network_type",UtilityNetworkKind(em,e)},{"power_line",em.HasComponent<PowerLineData>(e)},{"pipeline",em.HasComponent<PipelineData>(e)},{"marker",IsMarkerUtilityPrefab(em,e)},{"locked",RoadOperation.IsLocked(em,e)},{"width_m",g.m_DefaultWidth},{"max_slope",g.m_MaxSlopeSteepness},{"edge_length_m",new JObject{{"min",g.m_EdgeLengthRange.min},{"max",g.m_EdgeLengthRange.max}}},{"elevation_range_m",new JObject{{"min",d.m_ElevationRange.min},{"max",d.m_ElevationRange.max}}},{"construction_cost_per_m",d.m_DefaultConstructionCost},{"upkeep_cost_per_m",d.m_DefaultUpkeepCost},{"placement_flags",d.m_PlacementFlags.ToString()}};if(em.HasComponent<LocalConnectData>(e)){var l=em.GetComponentData<LocalConnectData>(e);row["connection_layers"]=l.m_Layers.ToString();row["snap_distance_m"]=d.m_SnapDistance;}return row;}
        private JObject ListUtilityNetworkPrefabs(JObject args,World world){string search=((string)args["search"]??"").Trim(),type=((string)args["network_type"]??"all").ToLowerInvariant();bool unlocked=(bool?)args["unlocked_only"]??true,markers=(bool?)args["include_markers"]??false;var rows=new List<JObject>();var em=world.EntityManager;foreach(var e in UtilityPrefabs(em)){var r=UtilityPrefabRow(world,e);if(!markers&&(bool)r["marker"]||unlocked&&(bool)r["locked"]||type!="all"&&(string)r["network_type"]!=type||search.Length>0&&((string)r["name"]??"").IndexOf(search,StringComparison.OrdinalIgnoreCase)<0)continue;rows.Add(r);}return new JObject{{"total",rows.Count},{"items",new JArray(rows.OrderBy(x=>(string)x["name"]))}};}
        private bool IsPermanentUtility(EntityManager em,Entity e)=>em.Exists(e)&&em.HasComponent<Edge>(e)&&em.HasComponent<Curve>(e)&&em.HasComponent<PrefabRef>(e)&&!em.HasComponent<Deleted>(e)&&!em.HasComponent<Temp>(e)&&IsUtilityPrefab(em,em.GetComponentData<PrefabRef>(e).m_Prefab);
        private JObject UtilityNetworkRow(World world,Entity e,bool detail){var em=world.EntityManager;var ps=world.GetExistingSystemManaged<PrefabSystem>();var p=em.GetComponentData<PrefabRef>(e).m_Prefab;ps.TryGetPrefab<PrefabBase>(p,out var pf);var c=em.GetComponentData<Curve>(e);var edge=em.GetComponentData<Edge>(e);var row=new JObject{{"utility_edge_id",m_Session+":"+e.Index+":"+e.Version},{"prefab",pf?.name},{"network_type",UtilityNetworkKind(em,p)},{"length_m",c.m_Length},{"start",PointJson(c.m_Bezier.a)},{"end",PointJson(c.m_Bezier.d)},{"start_node_id",m_Session+":"+edge.m_Start.Index+":"+edge.m_Start.Version},{"end_node_id",m_Session+":"+edge.m_End.Index+":"+edge.m_End.Version}};if(em.HasComponent<Elevation>(e)){var x=em.GetComponentData<Elevation>(e).m_Elevation;row["elevation_m"]=new JObject{{"start",x.x},{"end",x.y}};}if(detail){row["curve"]=new JObject{{"a",PointJson(c.m_Bezier.a)},{"b",PointJson(c.m_Bezier.b)},{"c",PointJson(c.m_Bezier.c)},{"d",PointJson(c.m_Bezier.d)}};var flows=new JArray();if(em.HasBuffer<ConnectedFlowEdge>(e)){var b=em.GetBuffer<ConnectedFlowEdge>(e,true);for(int i=0;i<b.Length;i++){var f=b[i].m_Edge;if(em.Exists(f)&&em.HasComponent<ElectricityFlowEdge>(f)){var d=em.GetComponentData<ElectricityFlowEdge>(f);flows.Add(new JObject{{"kind","electricity"},{"flow",d.m_Flow},{"capacity",d.m_Capacity},{"direction",d.direction.ToString()},{"bottleneck",d.isBottleneck},{"disconnected",d.isDisconnected}});}else if(em.Exists(f)&&em.HasComponent<WaterPipeEdge>(f)){var d=em.GetComponentData<WaterPipeEdge>(f);flows.Add(new JObject{{"kind","water_pipe"},{"fresh_flow",d.m_FreshFlow},{"fresh_capacity",d.m_FreshCapacity},{"fresh_pollution",d.m_FreshPollution},{"sewage_flow",d.m_SewageFlow},{"sewage_capacity",d.m_SewageCapacity},{"flags",d.m_Flags.ToString()}});}}}row["flow_edges"]=flows;}return row;}
        private JObject ListUtilityNetworks(JObject args,World world){string type=((string)args["network_type"]??"all").ToLowerInvariant();var rows=new List<JObject>();var em=world.EntityManager;using(var q=em.CreateEntityQuery(ComponentType.ReadOnly<Edge>(),ComponentType.ReadOnly<Curve>(),ComponentType.ReadOnly<PrefabRef>(),ComponentType.Exclude<Deleted>(),ComponentType.Exclude<Temp>()))using(var es=q.ToEntityArray(Allocator.Temp))foreach(var e in es)if(IsPermanentUtility(em,e)){var r=UtilityNetworkRow(world,e,false);if(type=="all"||(string)r["network_type"]==type)rows.Add(r);}return new JObject{{"total",rows.Count},{"items",new JArray(rows)}};}
        private JObject GetUtilityNetwork(JObject args,World world){var e=ParseEntity((string)args["utility_edge_id"],world.EntityManager);if(!IsPermanentUtility(world.EntityManager,e))throw new QueryException("UTILITY_EDGE_NOT_FOUND","utility_edge_id must identify a permanent utility network edge.");return UtilityNetworkRow(world,e,true);}
        private RoadEndpoint UtilityPoint(JObject value,World world,TerrainHeightData heights,Game.Net.Layer requestedMask){if(value==null)throw new QueryException("INVALID_ARGUMENT","Each point requires x and z.");var em=world.EntityManager;float elevation=BuildingNumber(value,"elevation_m",0,-50,50);var pos=new float3(BuildingNumber(value,"x",0,-7168,7168),0,BuildingNumber(value,"z",0,-7168,7168));Entity target=Entity.Null;float split=0;if(value["node_id"]!=null&&value["edge_id"]!=null)throw new QueryException("INVALID_ARGUMENT","Use node_id or edge_id, not both.");if(value["node_id"]!=null){target=ParseEntity((string)value["node_id"],em);if(!em.HasComponent<Node>(target)||em.HasComponent<Deleted>(target)||em.HasComponent<Temp>(target))throw new QueryException("INVALID_UTILITY_NODE","node_id must identify a permanent network node.");bool match=UtilityNodeSupports(em,target,requestedMask);if(!match&&em.HasBuffer<ConnectedEdge>(target)){var b=em.GetBuffer<ConnectedEdge>(target,true);for(int i=0;i<b.Length;i++)if(IsPermanentUtility(em,b[i].m_Edge)&&(UtilityNetworkMask(em,em.GetComponentData<PrefabRef>(b[i].m_Edge))&requestedMask)!=0){match=true;break;}}if(!match)throw new QueryException("INVALID_UTILITY_NODE","node_id is not compatible with the selected utility connection layer.");pos=em.GetComponentData<Node>(target).m_Position;}else if(value["edge_id"]!=null){target=ParseEntity((string)value["edge_id"],em);if(!IsPermanentUtility(em,target)||(UtilityNetworkMask(em,em.GetComponentData<PrefabRef>(target).m_Prefab)&requestedMask)==0)throw new QueryException("INVALID_UTILITY_EDGE","edge_id must identify a compatible utility connection layer.");var c=em.GetComponentData<Curve>(target).m_Bezier;MathUtils.Distance(c.xz,pos.xz,out split);pos=MathUtils.Position(c,split);if(math.distance(pos.xz,new float2(BuildingNumber(value,"x",0,-7168,7168),BuildingNumber(value,"z",0,-7168,7168)))>8)throw new QueryException("INVALID_UTILITY_EDGE","The point must be within 8 metres of edge_id.");}else pos.y=TerrainUtils.SampleHeight(ref heights,pos)+elevation;if(target!=Entity.Null&&math.abs(elevation)>.01f)throw new QueryException("INVALID_ENDPOINT","Attached endpoints inherit current elevation.");return new RoadEndpoint{Position=pos,Target=target,Split=split,Elevation=elevation};}
        private void ValidateUtilityCurve(Bezier4x3 curve,RoadEndpoint a,RoadEndpoint b,Entity prefab,EntityManager em){float length=MathUtils.Length(curve);var g=em.GetComponentData<NetGeometryData>(prefab);var p=em.GetComponentData<PlaceableNetData>(prefab);float min=math.max(8,g.m_EdgeLengthRange.min),max=g.m_EdgeLengthRange.max>0?g.m_EdgeLengthRange.max:300;if(length<min||length>max)throw new QueryException("INVALID_UTILITY_LENGTH","Each segment must fit the selected prefab length range and be at least 8 metres.");if(a.Target==Entity.Null&&(a.Elevation<p.m_ElevationRange.min||a.Elevation>p.m_ElevationRange.max)||b.Target==Entity.Null&&(b.Elevation<p.m_ElevationRange.min||b.Elevation>p.m_ElevationRange.max))throw new QueryException("INVALID_ELEVATION","Utility elevation is outside the prefab range.");float limit=g.m_MaxSlopeSteepness>0?g.m_MaxSlopeSteepness:1;var prev=curve.a;for(int i=1;i<=32;i++){var x=MathUtils.Position(curve,i/32f);if(math.abs(x.y-prev.y)/math.max(.01f,math.distance(x.xz,prev.xz))>limit)throw new QueryException("STEEP_SLOPE","Utility segment exceeds the prefab slope limit.");prev=x;}}
        private JObject UtilityOperationJson(RoadOperation op){var j=op.Json();j["utility_prefab"]=op.PrefabName;j["created_utility_edge_ids"]=j["created_road_ids"]?.DeepClone()??new JArray();j["target_utility_edge_ids"]=j["target_edge_ids"]?.DeepClone()??new JArray();j["note"]="Only completed confirms permanent utility network edges.";return j;}
        private JObject PreviewUtilityNetwork(JObject args,World world){string key=RequestKey(args),fingerprint=new JObject{{"kind","utility_network"},{"utility_prefab",args["utility_prefab"]?.DeepClone()},{"points",args["points"]?.DeepClone()}}.ToString(Formatting.None);if(m_RoadRequestIds.TryGetValue(key,out var oldId)){var old=m_RoadOperations[oldId];if(old.Fingerprint!=fingerprint||old.TransactionKind!="utility_network")throw new QueryException("IDEMPOTENCY_CONFLICT","request_id belongs to another operation.");return UtilityOperationJson(old);}if(!(args["points"] is JArray points)||points.Count<2||points.Count>16)throw new QueryException("INVALID_ARGUMENT","points must contain 2..16 utility points.");if(world.GetExistingSystemManaged<SimulationSystem>().selectedSpeed!=0)throw new QueryException("CITY_MUST_BE_PAUSED","Pause the city first.");var tool=RoadTool(world);if(tool.Busy||!(world.GetExistingSystemManaged<ToolSystem>().activeTool is DefaultToolSystem))throw new QueryException("TOOL_BUSY","Select the default tool and finish another preview.");var em=world.EntityManager;var prefab=ResolveUtilityPrefab((string)args["utility_prefab"],world);if(RoadOperation.IsLocked(em,prefab))throw new QueryException("UTILITY_PREFAB_LOCKED","The selected utility prefab is locked.");var heights=world.GetExistingSystemManaged<TerrainSystem>().GetHeightData(true);if(!heights.isCreated)throw new QueryException("TERRAIN_UNAVAILABLE","Terrain heights are unavailable.");var requestedMask=UtilityNetworkMask(em,prefab);if(requestedMask==Game.Net.Layer.None)throw new QueryException("INVALID_UTILITY_PREFAB","The selected prefab does not expose a utility connection layer.");var parsed=points.Select(x=>UtilityPoint(x as JObject,world,heights,requestedMask)).ToList();var op=new RoadOperation{Session=m_Session,RequestId=key,Fingerprint=fingerprint,OperationType="create",TransactionKind="utility_network",Prefab=prefab,PrefabName=(string)args["utility_prefab"],CurveMode="polyline"};for(int i=0;i+1<parsed.Count;i++){var a=parsed[i];var b=parsed[i+1];var c=NetUtils.StraightCurve(a.Position,b.Position);ValidateUtilityCurve(c,a,b,prefab,em);op.Segments.Add(new RoadSegmentPlan{Start=a.Position,End=b.Position,StartTarget=a.Target,EndTarget=b.Target,StartSplit=a.Split,EndSplit=b.Split,StartElevation=a.Elevation,EndElevation=b.Elevation,Curve=c});}var f=op.Segments[0];var l=op.Segments[op.Segments.Count-1];op.Start=f.Start;op.End=l.End;op.StartNode=f.StartTarget;op.EndNode=l.EndTarget;op.StartSplit=f.StartSplit;op.EndSplit=l.EndSplit;op.StartElevation=f.StartElevation;op.EndElevation=l.EndElevation;op.Curve=f.Curve;tool.Begin(op);m_RoadOperations.Add(op.Id,op);m_RoadRequestIds.Add(key,op.Id);return UtilityOperationJson(op);}
        private JObject PreviewUtilityExisting(JObject args,World world,bool upgrade){string key=RequestKey(args),kind=upgrade?"utility_upgrade":"utility_delete";var fingerprint=new JObject{{"kind",kind},{"utility_prefab",args["utility_prefab"]?.DeepClone()},{"utility_edge_ids",args["utility_edge_ids"]?.DeepClone()}}.ToString(Formatting.None);if(m_RoadRequestIds.TryGetValue(key,out var oldId)){var old=m_RoadOperations[oldId];if(old.Fingerprint!=fingerprint||old.TransactionKind!="utility_network")throw new QueryException("IDEMPOTENCY_CONFLICT","request_id belongs to another operation.");return UtilityOperationJson(old);}if(!(args["utility_edge_ids"] is JArray ids)||ids.Count<1||ids.Count>64)throw new QueryException("INVALID_ARGUMENT","utility_edge_ids must contain 1..64 edges.");if(world.GetExistingSystemManaged<SimulationSystem>().selectedSpeed!=0)throw new QueryException("CITY_MUST_BE_PAUSED","Pause the city first.");var tool=RoadTool(world);if(tool.Busy||!(world.GetExistingSystemManaged<ToolSystem>().activeTool is DefaultToolSystem))throw new QueryException("TOOL_BUSY","Select the default tool and finish another preview.");var em=world.EntityManager;Entity prefab=upgrade?ResolveUtilityPrefab((string)args["utility_prefab"],world):Entity.Null;var op=new RoadOperation{Session=m_Session,RequestId=key,Fingerprint=fingerprint,OperationType=upgrade?"batch_upgrade":"batch_demolish",TransactionKind="utility_network",Prefab=prefab,PrefabName=upgrade?(string)args["utility_prefab"]:null,CurveMode="existing"};var unique=new HashSet<Entity>();string family=null;foreach(var token in ids){var e=ParseEntity((string)token,em);if(!unique.Add(e))throw new QueryException("DUPLICATE_UTILITY_EDGE","utility_edge_ids must be unique.");if(!IsPermanentUtility(em,e))throw new QueryException("UTILITY_EDGE_NOT_FOUND","Every ID must identify a permanent utility edge.");var p=em.GetComponentData<PrefabRef>(e).m_Prefab;string k=UtilityNetworkKind(em,p);if(family==null)family=k;if(upgrade&&(k!=family||UtilityNetworkKind(em,prefab)!=family))throw new QueryException("INCOMPATIBLE_UTILITY_PREFAB","Upgrade targets and replacement must have the same network type.");var edge=em.GetComponentData<Edge>(e);var c=em.GetComponentData<Curve>(e).m_Bezier;var elevation=em.HasComponent<Elevation>(e)?em.GetComponentData<Elevation>(e).m_Elevation:new float2(0);op.TargetEdges.Add(e);op.Segments.Add(new RoadSegmentPlan{TargetEdge=e,OriginalPrefab=p,Start=c.a,End=c.d,StartTarget=edge.m_Start,EndTarget=edge.m_End,StartElevation=elevation.x,EndElevation=elevation.y,Curve=c});}if(!upgrade){op.Prefab=op.Segments[0].OriginalPrefab;op.PrefabName=world.GetExistingSystemManaged<PrefabSystem>().GetPrefab<PrefabBase>(op.Prefab).name;}var first=op.Segments[0];op.TargetEdge=op.TargetEdges[0];op.Start=first.Start;op.End=op.Segments[op.Segments.Count-1].End;op.StartNode=first.StartTarget;op.EndNode=op.Segments[op.Segments.Count-1].EndTarget;op.Curve=first.Curve;tool.Begin(op);m_RoadOperations.Add(op.Id,op);m_RoadRequestIds.Add(key,op.Id);return UtilityOperationJson(op);}
        private RoadOperation UtilityOperation(JObject args){var op=RoadOperationById(args);if(op.TransactionKind!="utility_network")throw new QueryException("UTILITY_OPERATION_NOT_FOUND","operation_id does not identify a utility operation.");return op;}
        private JObject GetUtilityOperation(JObject args)=>UtilityOperationJson(UtilityOperation(args));
        private JObject ApplyUtilityOperation(JObject args){UtilityOperation(args);CommitRoad(args);return UtilityOperationJson(UtilityOperation(args));}
        private JObject CancelUtilityOperation(JObject args){var op=UtilityOperation(args);CancelRoad(args);return UtilityOperationJson(op);}
    }
